Using Built-in Swap MethodsWe can also swap using built-in functionalities like swap() function in C++, tuple unpacking in Python, destructuring assignment in JavaScript. 
            C++

    // C++ Code to swap two numbers using swap function

#include <iostream>
using namespace std;

int main() {
    int a = 10, b = 20;

    swap(a, b);

    cout  << a << " " << b << endl;
    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int a = 10, b = 20;
    swap(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}


